+    uint32_t padScIdx = 0U;        // 当前sc输出位置，TH场景为全局的dealedScCnt，BSH场景则为填充后全局的索引（Reset刷新）
+    uint32_t loopDealedScCnt = 0U; // 当前迭代已处理的sc数量（Reset刷新）
